import {parseCSV,normalizeRecords,analyze,exportPlan,categoryColors,csvCell} from './engine.js';
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M7 17 17 7M7 7h10v10',upload:'M12 16V3m-5 5 5-5 5 5M4 16v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4',chevron:'m9 5 7 7-7 7',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z M8 12l3 3 5-6',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Zm0 0v6h6M8 13h8M8 17h6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',wallet:'M20 7V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6m14 7h6v4h-6z',repeat:'m17 2 4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4m14-1v2a3 3 0 0 1-3 3H3',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',lock:'M5 11h14v10H5zm3 0V7a4 4 0 0 1 8 0v4',check:'m5 12 4 4L19 6',info:'M12 8h.01M12 11v6m9-5a9 9 0 1 1-18 0 9 9 0 0 1 18 0',chart:'M3 3v18h18M7 16v-4m5 4V8m5 8V5',code:'m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 18',close:'m6 6 12 12M6 18 18 6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z'};
const icon=(n,cls='')=>`<svg class="${cls}" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${(paths[n]||paths.spark).split('Z ').map(d=>`<path d="${d}"/>`).join('')}</svg>`;
let state={report:null,currency:'KZT',mode:'positive',files:[],error:'',demo:false,approved:[],tab:'overview',query:'',category:'all',limit:100,loading:false};
const money=(n,short=false)=>new Intl.NumberFormat('en-US',{style:'currency',currency:state.currency,maximumFractionDigits:short?0:2,minimumFractionDigits:short?0:2}).format(n);
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const color=n=>categoryColors[n]||'#b8b5ae';
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function download(filename,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function nav(){const onReport=location.hash==='#report'&&state.report;return `<header class="topbar"><a href="#upload" class="logo" aria-label="SpendLens home"><span class="logo-icon"></span>SpendLens<span style="color:#a1ad8c;font-size:16px">.</span></a><nav class="navigation" aria-label="Main navigation"><a href="#upload" class="${!onReport?'active':''}">Upload</a><a href="#report" class="${onReport?'active':''}">Your report</a></nav><div class="user"><span class="shield">${icon('shield')} Private by design</span><span class="avatar">SL</span></div></header>`;}
function footer(){return `<footer class="footer"><span>© 2026 SpendLens. Make room for what matters.</span><span>Team Azomye <span style="margin:0 8px">·</span> <a href="https://github.com/yesb-fn/spendlens-fintechathon" target="_blank" rel="noopener noreferrer">FinTechathon 2026 ↗</a></span></footer>`;}
function upload(){return `<main><section class="upload-layout"><div class="intro"><div class="eyebrow"><i></i> YOUR MONEY, A LITTLE CLEARER</div><h1>Less spending.<br><em>More possibility.</em></h1><p class="lead">Give your expenses a closer look. Find the small leaks, rethink recurring costs, and make room for the things you love.</p><div class="steps"><div class="step"><span class="step-number">01</span><div><strong>Bring your expenses</strong><small>Upload a transaction export. We’ll do the sorting.</small></div></div><div class="step"><span class="step-number">02</span><div><strong>Discover your opportunities</strong><small>Spot spending patterns and places you could save.</small></div></div><div class="step"><span class="step-number">03</span><div><strong>Turn insights into action</strong><small>Export a plan for your AI agent. Stay in control.</small></div></div></div><div class="quote">${icon('lock')} Your files stay in your browser. No bank login needed.</div></div><div class="upload-card"><div class="card-heading"><div><h2>A fresh look at your finances</h2><p>Start with a bank or expense-tracker export.</p></div><span class="pill">${icon('shield')} Local & secure</span></div>${state.loading?`<div class="loading"><div class="spinner"></div><strong>Looking for the bigger picture…</strong><small>Calculating categories and payment patterns.</small></div>`:`<div class="dropzone" id="dropzone"><div class="upload-symbol">${icon('upload')}</div><strong>Drag & drop your expense files</strong><p>CSV or JSON · up to 10 MB total</p><input class="upload-file" id="files" type="file" accept=".csv,.json,text/csv,application/json" multiple aria-label="Choose expense files"><button class="button secondary" id="choose">Browse files ${icon('chevron')}</button></div><div class="template">Not sure about the format? <a href="#" id="sample">Download a sample CSV ↗</a></div>${state.files.map((f,i)=>`<div class="file-status">${icon('file')}<span>${esc(f.name)}</span><small>${f.records.length} rows</small><button class="remove" data-remove="${i}" aria-label="Remove ${esc(f.name)}">×</button></div>`).join('')}<div class="upload-options"><div class="field"><label for="currency">REPORT CURRENCY</label><select id="currency">${['KZT','USD','EUR','GBP'].map(c=>`<option ${state.currency===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="sign">EXPENSE AMOUNTS</label><select id="sign"><option value="positive" ${state.mode==='positive'?'selected':''}>Positive amounts</option><option value="negative" ${state.mode==='negative'?'selected':''}>Negative bank debits</option></select></div></div>${state.error?`<div class="error" role="alert">${esc(state.error)}</div>`:''}<button id="analyze" class="button primary full">Find my savings ${icon('arrow')}</button><div class="divider">OR TAKE A LOOK AROUND</div><button class="button demo-button full" id="demo">Explore a sample report ${icon('arrow')}</button><p class="card-note">No account. No connected bank. Just a clearer picture.<br>CSV: date, merchant, amount. Optional: category, type.</p>`}</div></section><section class="feature-row" aria-label="How SpendLens helps"><div><span class="mini-icon">${icon('chart')}</span><div><strong>See the whole picture</strong><p>Your biggest expenses, repeated payments and subscriptions, in one place.</p></div></div><div><span class="mini-icon">${icon('spark')}</span><div><strong>Keep what matters</strong><p>Review lower-cost options against the features and value you care about.</p></div></div><div><span class="mini-icon">${icon('code')}</span><div><strong>Ready for your AI agent</strong><p>A structured savings plan, with your approval built into every next step.</p></div></div></section>${footer()}</main>`;}
function metric(label,value,note,ico,highlight=false){return `<article class="metric ${highlight?'highlight':''}"><div class="metric-top">${label}${icon(ico)}</div><div class="metric-value">${value}</div><small>${note}</small></article>`;}
function panelHead(title,subtitle,extra=''){return `<div class="panel-head"><div><h2>${title}</h2><p>${subtitle}</p></div>${extra}</div>`;}
function approval(a){return `<label class="approval"><input type="checkbox" data-approve="${esc(a.id)}" ${state.approved.includes(a.id)?'checked':''}> Approve for agent research</label>`;}
function exportPanel(){return `<section class="export-panel"><div class="export-icon">${icon('code')}</div><div class="export-copy"><h2>Your insights. Ready for the next step.</h2><p>Send a structured savings plan to your AI agent. Approval covers research only; changing plans or making payments always needs your confirmation.</p></div><button class="button primary" data-export="json">Export agent plan ${icon('download')}</button></section>`;}
function overview(r){let stop=0;const grad=r.categories.map(c=>{const from=stop;stop+=c.amount/r.total*100;return`${color(c.name)} ${from}% ${stop}%`;}).join(',');const top=r.categories[0];return `<div class="dashboard-grid"><section class="panel">${panelHead('Where your money goes','Every category, in perspective.',`<span class="tiny-label">${r.months} ${r.months===1?'month':'months'} observed</span>`)}<div class="chart-area"><div class="donut" role="img" aria-label="Expense categories: ${esc(r.categories.map(c=>c.name+' '+Math.round(c.amount/r.total*100)+'%').join(', '))}" style="background:conic-gradient(${grad})"><div class="donut-label"><small>TOTAL SPENT</small><strong>${money(r.total,true)}</strong></div></div><div class="legend">${r.categories.slice(0,6).map(c=>`<div class="legend-row"><i class="dot" style="background:${color(c.name)}"></i><span class="name">${esc(c.name)}</span><strong>${money(c.amount,true)}</strong><small>${Math.round(c.amount/r.total*100)}%</small></div>`).join('')}${r.categories.length>6?`<div class="legend-row"><span class="name">+ ${r.categories.length-6} more categories</span></div>`:''}</div></div><div class="insight-strip">${icon('spark')}<span><strong>${esc(top.name)}</strong> is your largest category — ${Math.round(top.amount/r.total*100)}% of all expenses in this period.</span></div></section><section class="panel">${panelHead('The biggest expense sources','A closer look at your top merchants.',`<span class="tiny-label">By total spend</span>`)}${r.merchants.slice(0,5).map((g,i)=>`<div class="source-row"><span class="source-icon" style="background:${color(g.category)}22">${String(i+1).padStart(2,'0')}</span><div><div class="source-name">${esc(g.name)}</div><div class="source-count">${g.count} ${g.count===1?'transaction':'transactions'} · ${esc(g.category)}</div></div><div class="source-amount">${money(g.total,true)}<div class="bar"><span style="width:${Math.max(5,g.total/r.merchants[0].total*100)}%;min-width:6px"></span></div></div></div>`).join('')}</section></div><div class="lower-grid"><section class="panel">${panelHead('The payments that keep coming back',`${r.subscriptions.length} subscriptions & likely regular bills.`,r.subscriptions.length?'<button class="link-button" data-tab="recurring">View all ↗</button>':'')} ${r.subscriptions.length?r.subscriptions.slice(0,4).map(g=>subscriptionRow(g,r)).join(''):'<div class="empty">No clear subscriptions or regular bills found.<br>Try a statement covering several months.</div>'}</section><section class="panel">${panelHead('Small changes. Meaningful savings.','Illustrative targets, ready for a closer comparison.','<span class="pill">Ideas for you</span>')}${r.actions.length?r.actions.slice(0,3).map(a=>`<article class="savings-card"><div class="savings-top"><div><h3>${esc(a.title)}</h3><p>${esc(a.merchant)} · ${esc(a.kind)}</p></div><span class="savings-badge">~${money(a.saving,true)}/mo</span></div>${approval(a)}</article>`).join(''):'<div class="empty">No specific savings ideas for these expenses yet. Add more transaction history to reveal patterns.</div>'}</section></div>${exportPanel()}`;}
function subscriptionRow(g,r){return `<div class="subscription-row"><span class="service-icon" style="background:${color(g.category)}28;color:#657c4b">${esc(g.name.charAt(0).toUpperCase())}</span><div class="service-text"><strong>${esc(g.name)}</strong><small>${g.subscription?'Likely subscription':'Likely monthly bill'} · ${g.count} ${g.count===1?'payment':'payments'}</small></div><div class="service-price">${money(g.monthlyEstimate)}<small>observed monthly avg.</small></div></div>`;}
function recurring(r){return `<div class="dashboard-grid"><section class="panel">${panelHead('Subscriptions & regular bills','Detected from merchant names and monthly payment patterns.')}<p class="notice">These are likely recurring payments, not confirmed contracts. A name match can be wrong; verify the merchant and billing terms.</p>${r.subscriptions.map(g=>subscriptionRow(g,r)).join('')||'<div class="empty">No recurring payment patterns detected.</div>'}</section><section class="panel">${panelHead('Repeated expense sources','Merchants with two or more expenses in your file.')}<div class="table-wrap"><table><thead><tr><th>Merchant</th><th>Payments</th><th>Total</th></tr></thead><tbody>${r.repeated.map(g=>`<tr><td>${esc(g.name)}</td><td>${g.count}</td><td>${money(g.total)}</td></tr>`).join('')}</tbody></table></div>${!r.repeated.length?'<div class="empty">No repeated merchants found.</div>':''}</section></div>${exportPanel()}`;}
function transactions(r){const q=state.query.toLowerCase();const list=r.transactions.filter(t=>(state.category==='all'||t.category===state.category)&&(!q||[t.merchant,t.date,t.category].join(' ').toLowerCase().includes(q))).slice().reverse();return `<section class="panel">${panelHead('Every expense, accounted for',`${r.transactions.length} valid expenses · ${esc(state.filename)}.`)}<div class="table-tools"><label class="sr-only" for="search">Search transactions</label><input id="search" class="search" placeholder="Search merchant or date…" value="${esc(state.query)}"><label class="sr-only" for="category">Filter category</label><select class="filter" id="category"><option value="all">All categories</option>${r.categories.map(c=>`<option value="${esc(c.name)}" ${state.category===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button class="button subtle" data-export="csv">Export CSV ${icon('download')}</button></div><div id="transaction-results"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Merchant</th><th>Category</th><th>Amount</th></tr></thead><tbody>${list.slice(0,state.limit).map(t=>`<tr><td style="white-space:nowrap">${date(t.date)}</td><td>${esc(t.merchant)}</td><td><span class="dot" style="display:inline-block;background:${color(t.category)};margin-right:7px"></span>${esc(t.category)}</td><td>${money(t.amount)}</td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">No transactions match your search.</div>':''}<p class="page-counter">Showing ${Math.min(state.limit,list.length)} of ${list.length} matching expenses.</p>${list.length>state.limit?'<button class="button secondary" id="loadmore">Show more transactions</button>':''}</div></section>`;}
function actions(r){return `<p class="notice">All savings below are scenario estimates. Prices, eligibility, taxes and feature equivalence have not been verified. An agent should research official offers and ask you before acting.</p><div class="action-list">${r.actions.map(a=>`<article class="action-item"><div class="savings-top"><span class="pill">${esc(a.kind)}</span><span class="savings-badge">~${money(a.saving,true)}/mo potential</span></div><h3>${esc(a.title)}</h3><p><strong>${esc(a.merchant)}</strong> — ${esc(a.explanation)}</p><div class="action-amounts"><div><small>OBSERVED / MONTH</small><strong>${money(a.current)}</strong></div><div><small>ILLUSTRATIVE TARGET</small><strong style="color:#819f54">${money(a.estimated)}</strong></div></div><p class="data-notice">${esc(a.assumption)}</p>${a.search?`<a class="text-link" href="${esc(a.search)}" target="_blank" rel="noopener noreferrer">Research official plans ↗</a>`:''}${approval(a)}</article>`).join('')}</div>${!r.actions.length?'<div class="panel empty">No specific savings ideas yet. You can still export the transaction analysis.</div>':''}${exportPanel()}`;}
function report(){const r=state.report;const saving=r.actions.reduce((s,a)=>s+a.saving,0);const monthly=r.subscriptions.reduce((s,g)=>s+g.monthlyEstimate,0);return `<main class="report"><div class="report-heading"><div><p class="breadcrumb">YOUR SPENDING, IN FOCUS</p><h1>A little clarity goes a long way.</h1><p class="report-sub">${date(r.start)} – ${date(r.end)} <span>•</span> ${state.demo?'Sample data':esc(state.filename)} <span>•</span> ${state.currency}</p></div><div class="heading-actions"><a href="#upload" class="button secondary">${icon('upload')} New upload</a><button class="button primary" id="print">Download report ${icon('download')}</button></div></div><div class="metrics">${metric('Total expenses',money(r.total,true),`${r.transactions.length} expenses across ${r.months} observed months`,'wallet')}${metric('Recurring payments',money(monthly,true),`${r.subscriptions.length} likely bills & subscriptions · monthly avg.`,'repeat')}${metric('Repeated sources',r.repeated.length,'Merchants appearing more than once','layers')}${metric('Potential monthly savings','~'+money(saving,true),'Illustrative estimates · subject to verification','spark',true)}</div><div class="settings-bar"><span>${state.demo?'You’re exploring fictional sample data.':'Local analysis • data stays in this browser tab.'}</span><span>${state.approved.length} actions approved for research</span></div>${state.imported&&(state.imported.income||state.imported.invalid)?`<p class="data-notice">Import summary: ${r.transactions.length} expenses included; ${state.imported.income} income, refunds or opposite-sign amounts excluded; ${state.imported.invalid} invalid rows skipped. No currency conversion is performed.</p>`:''}<nav class="report-tabs" aria-label="Report sections">${[['overview','Overview'],['recurring','Recurring & subscriptions'],['transactions','All transactions'],['actions','Savings plan']].map(([id,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}" aria-current="${state.tab===id?'page':'false'}">${label}${id==='actions'?` <span class="count">${r.actions.length}</span>`:''}</button>`).join('')}</nav>${state.tab==='overview'?overview(r):state.tab==='recurring'?recurring(r):state.tab==='transactions'?transactions(r):actions(r)}<p class="report-note">${icon('info')} SpendLens is a prototype using local rules, not a live financial adviser. Monthly figures average the distinct calendar months in your file and may be skewed by partial months. No subscriptions are changed automatically.</p>${footer()}</main>`;}
function render(){const show=location.hash==='#report'&&state.report;$('#app').innerHTML=nav()+(show?report():upload());bind();}
function csv(records){const cell=csvCell;return[['date','merchant','amount','category','type'],...records.map(r=>[r.date,r.merchant,r.amount,r.category||'','expense'])].map(r=>r.map(cell).join(',')).join('\n');}
function sample(){const rows=[];for(let m=7;m<=9;m++){const mo=String(m).padStart(2,'0');for(const [day,merchant,amount,category] of [[1,'Apartment rent',820,'Housing & bills'],[3,'Spotify',10.99,'Subscriptions'],[5,'Netflix',15.49,'Subscriptions'],[6,'Notion',12,'Subscriptions'],[8,'Internet bill',45,'Housing & bills'],[10,'iCloud storage',2.99,'Subscriptions'],[12,'City gym',40,'Health & fitness'],[14,'Magnum Market',96+m,'Groceries'],[22,'Magnum Market',82+m,'Groceries'],[16,'Zara',m===7?118:67,'Shopping'],[18,'Amazon',69+m,'Shopping']])rows.push({date:`2026-${mo}-${String(day).padStart(2,'0')}`,merchant,amount,category});for(let d=2;d<29;d+=4)rows.push({date:`2026-${mo}-${String(d).padStart(2,'0')}`,merchant:d%3===0?'Wolt delivery':'Corner Coffee',amount:d%3===0?24.5:8.8,category:'Food & dining'});for(let d=4;d<26;d+=6)rows.push({date:`2026-${mo}-${String(d).padStart(2,'0')}`,merchant:'Yandex Go',amount:9.4+d/5,category:'Transport'});}return rows;}
async function readFiles(files){state.error='';const combined=[...state.files];let size=combined.reduce((s,f)=>s+f.size,0);try{for(const file of files){size+=file.size;if(size>10*1024*1024)throw new Error('Please keep the combined files under 10 MB.');const ext=file.name.split('.').pop().toLowerCase();if(!['csv','json'].includes(ext))throw new Error('Please export your statement as CSV or JSON. PDF and XLSX are not supported in this prototype.');const text=await file.text();let records;if(ext==='json'){const parsed=JSON.parse(text);records=Array.isArray(parsed)?parsed:parsed.transactions;if(!Array.isArray(records))throw new Error('JSON must be an array of transactions, or an object with a transactions array.');}else records=parseCSV(text);if(records.length>30000)throw new Error('Please use up to 30,000 rows per file.');combined.push({name:file.name,size:file.size,records});}state.files=combined;}catch(e){state.error=e.message;}render();}
function startAnalysis(demo=false){if(!demo&&!state.files.length){state.error='Choose at least one CSV or JSON expense file, or explore the sample report.';render();return;}state.loading=true;state.error='';render();requestAnimationFrame(()=>setTimeout(()=>{try{let transactions=[],invalid=0,income=0;if(demo){transactions=normalizeRecords(sample()).transactions;state.currency='USD';}else{for(const f of state.files){const r=normalizeRecords(f.records,{mode:state.mode});transactions.push(...r.transactions);invalid+=r.invalid;income+=r.income;}}transactions.forEach((t,i)=>t.id=i+1);state.report=analyze(transactions);state.imported={invalid,income};state.demo=demo;state.filename=demo?'sample-expenses.csv':state.files.map(f=>f.name).join(', ');state.approved=[];state.tab='overview';state.query='';state.category='all';state.limit=100;state.loading=false;location.hash='report';render();window.scrollTo({top:0});}catch(e){state.error=e.message;state.loading=false;render();}},50));}
function doExport(type){const r=state.report;const plan=exportPlan(r,state.currency,state.approved);if(type==='json'){download('spendlens-agent-plan.json',JSON.stringify({...plan,expense_summary:{total_spent:r.total,categories:r.categories,largest_merchants:r.merchants.slice(0,10).map(g=>({name:g.name,total:g.total,count:g.count}))}},null,2),'application/json');toast('Agent plan exported. Every external action still needs confirmation.');}else if(type==='csv'){download('spendlens-expenses.csv',csv(r.transactions),'text/csv');toast('Categorized expenses exported.');}}
function bind(){if($('#choose')){$('#choose').onclick=()=>$('#files').click();$('#files').onchange=e=>readFiles(e.target.files);const dz=$('#dropzone');['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add('drag');}));['dragleave','drop'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove('drag');}));dz.ondrop=e=>readFiles(e.dataTransfer.files);$('#currency').onchange=e=>state.currency=e.target.value;$('#sign').onchange=e=>state.mode=e.target.value;$('#sample').onclick=e=>{e.preventDefault();download('spendlens-sample.csv',csv(sample()),'text/csv');};$('#analyze').onclick=()=>startAnalysis();$('#demo').onclick=()=>startAnalysis(true);document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.files.splice(Number(b.dataset.remove),1);render();});}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render();});document.querySelectorAll('[data-approve]').forEach(c=>c.onchange=()=>{const id=c.dataset.approve;state.approved=c.checked?[...new Set([...state.approved,id])]:state.approved.filter(x=>x!==id);render();});document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>doExport(b.dataset.export));if($('#print'))$('#print').onclick=()=>{toast('Choose “Save as PDF” in the print dialog.');window.print();};if($('#category'))$('#category').onchange=e=>{state.category=e.target.value;state.limit=100;render();};if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;state.query=e.target.value;state.limit=100;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};if($('#loadmore'))$('#loadmore').onclick=()=>{state.limit+=100;render();};}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});render();
